    { const nr = await scwin.tx_fn_goPage(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil53100/jldfil53100.xml", { "method": 'searchPubOfrSchdl' }); } };
